insert into public.quotes (id, lang, text, translation, translation_by, author, author_alt, work, year, source_url, source_note, verified_on) values
('en-thoreau-walden-castles', 'en', 'If you have built castles in the air, your work need not be lost; that is where they should be. Now put the foundations under them.', 'إن كنتَ قد بنيتَ قصورًا في الهواء، فعملك لم يضِع؛ فهناك مكانها. والآن ضع الأساسات تحتها.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 18 “Conclusion”', '1854', 'https://www.literaturepage.com/read/walden-243.html', 'Public domain.', '2026-11-03'),
('en-tennyson-ulysses-strive', 'en', 'To strive, to seek, to find, and not to yield.', 'أن نجاهد، وأن نسعى، وأن نجد، وألّا نستسلم.', 'app', 'Alfred, Lord Tennyson', 'ألفريد تينيسون', 'Ulysses (final line)', '1842', 'https://rpo.library.utoronto.ca/poems/ulysses', 'Public domain. The source prints the line in lower case as the end of a sentence; capitalized here as a standalone excerpt.', '2026-11-03'),
('en-emerson-self-reliance-trust', 'en', 'Trust thyself: every heart vibrates to that iron string.', 'ثِق بنفسك: كل قلبٍ يهتز لذلك الوتر الحديدي.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance (Essays: First Series)', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain.', '2026-11-03'),
('en-shakespeare-measure-doubts', 'en', 'Our doubts are traitors, / And make us lose the good we oft might win, / By fearing to attempt.', 'شكوكنا خونة، تُضيّع علينا الخير الذي كان يمكن أن نكسبه، لأننا نخاف أن نحاول.', 'app', 'William Shakespeare', 'وليم شكسبير', 'Measure for Measure, Act 1, Scene 4 (Lucio)', 'c. 1603–1604', 'https://absoluteshakespeare.com/plays/measure_for_measure/a1s4.htm', 'Public domain. Punctuation follows the linked edition; other editions omit the comma after “win”.', '2026-11-03'),
('ar-mutanabbi-ghamarta', 'ar', 'إِذا غامَرتَ في شَرَفٍ مَرومٍ ... فَلا تَقنَع بِما دونَ النُجومِ', 'If you venture after a coveted honor, do not settle for anything below the stars.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «إذا غامرت في شرف مروم» — الديوان', 'القرن الرابع الهجري / 10th century', 'https://www.aldiwan.net/poem10566.html', 'ملكية عامة. النص كما في صفحة الديوان المرتبطة.', '2026-11-03'),
('ar-shabbi-iradat-al-hayat-jibal', 'ar', 'ومن لا يحبُّ صُعودَ الجبالِ ... يَعِشْ أبَدَ الدَّهرِ بَيْنَ الحُفَرْ', 'Whoever does not love climbing mountains will live forever among the pits.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة (توفي الشاعر 1934). تشتهر رواية «ومن يتهيّب صعود الجبال»؛ المعروض هنا هو نص المصدر المرتبط.', '2026-11-03')
